      q.guardian = null;
      const txt = `${q.name}\u304C\u5143\u670D\u3057\u3001\u307F\u305A\u304B\u3089\u5BB6\u7763\u3092\u57F7\u3063\u305F\u3002${gd ? `${gd.name}\u306E\u5F8C\u898B\u306F\u89E3\u3051\u305F\u3002` : ""}`;
